/* 학습 해설
 * DTB node 이름 비교·unit address를 생략한 탐색
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 기존 이름 길이가 요청보다 짧거나 앞 byte가 다르면 실패합니다. 요청 뒤 기존 이름이 NUL이면 정확히 일치하고, 요청에 @가 없으며 기존 다음 문자가 @이면 unit address를 생략한 이름도 일치합니다. 임의 접두사를 모두 허용하는 검색은 아닙니다.
 * ethernet@100을 ethernet으로 찾되 ethernet@999는 일치하지 않는 실제 fixture를 비교합니다. 여러 같은 기본 이름의 child가 있을 때 첫 탐색 결과와 완전한 식별을 구별합니다.
 */
static int fdt_nodename_eq_(const void *fdt, int offset,
			    const char *s, int len)
{
	int olen;
	const char *p = fdt_get_name(fdt, offset, &olen);

	if (!p || olen < len)
		/* short match */
		return 0;

	if (memcmp(p, s, len) != 0)
		return 0;

	if (p[len] == '\0')
		return 1;
	else if (!memchr(s, '@', len) && (p[len] == '@'))
		return 1;
	else
		return 0;
}

const char *fdt_get_string(const void *fdt, int stroffset, int *lenp)
{
	int32_t totalsize;
	uint32_t absoffset;
	size_t len;

