/* 학습 해설
 * DTB 문자열 조회·최소 probe와 절대 offset
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 기본 경로는 ro_probe로 총길이와 상태를 확인하고 strings base+stroffset의 절대 위치를 계산해 total 안인지 검사합니다. 완성 tree의 negative string offset은 거부합니다. VALID_INPUT 전제 경로는 직접 pointer와 strlen을 사용하므로 caller가 정상 NUL 문자열 위치를 보장해야 합니다.
 * 완성 자료의 stroffset -1 오류와 정상 property nameoff를 대조합니다. 상대 위치·절대 위치·length out parameter를 구별하고 검사 생략 문맥을 별도 조건으로 읽습니다.
 */
const char *fdt_get_string(const void *fdt, int stroffset, int *lenp)
{
	int32_t totalsize;
	uint32_t absoffset;
	size_t len;
	int err;
	const char *s, *n;

	if (can_assume(VALID_INPUT)) {
		s = (const char *)fdt + fdt_off_dt_strings(fdt) + stroffset;

		if (lenp)
			*lenp = strlen(s);
		return s;
	}
	totalsize = fdt_ro_probe_(fdt);
	err = totalsize;
	if (totalsize < 0)
		goto fail;

	err = -FDT_ERR_BADOFFSET;
	absoffset = stroffset + fdt_off_dt_strings(fdt);
	if (absoffset >= (unsigned)totalsize)
		goto fail;
	len = totalsize - absoffset;

