/* 학습 해설
 * DTB phandle 생성·최대값 다음 번호와 소진
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 최대 phandle을 얻고 정확히 FDT_MAX_PHANDLE이면 NOPHANDLES, 아니면 max+1을 out parameter로 전달합니다. 유효 tree와 phandle 범위를 전제로 번호를 제안하는 함수입니다. 값의 존재 여부를 별도 hash로 재검사하거나 할당 동시성을 lock으로 제공하지 않습니다.
 * max2에서 후보3을 계산합니다. get_phandle이 raw32값을 읽는 점과 이 함수의 equality 상한 검사를 함께 읽어 임의 잘못된 값의 안전한 정규화라고 주장하지 않습니다.
 */
int fdt_generate_phandle(const void *fdt, uint32_t *phandle)
{
	uint32_t max;
	int err;

	err = fdt_find_max_phandle(fdt, &max);
	if (err < 0)
		return err;

	if (max == FDT_MAX_PHANDLE)
		return -FDT_ERR_NOPHANDLES;

	if (phandle)
		*phandle = max + 1;

	return 0;
}

