/* 학습 해설
 * DTB reserve pointer·entry stride와 bounds
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * n*sizeof(entry)로 상대 offset을 계산하고 reserve base를 더합니다. 기본 검사는 base보다 작아지는 wrap와 마지막 entry가 total 밖에 나가는 조건을 확인합니다. 정상 pointer는 원본 내부 reserve helper로 얻으며 cell 주소 형식이 아니라 고정16바이트 entry 배열입니다.
 * n0/1과 큰 n1000을 실제 fixture에서 비교합니다. byte offset과 entry index를 구별하며 모든 임의 int 경계 조합을 실행 검증한 것은 아님을 적습니다.
 */
static const struct fdt_reserve_entry *fdt_mem_rsv(const void *fdt, int n)
{
	unsigned int offset = n * sizeof(struct fdt_reserve_entry);
	unsigned int absoffset = fdt_off_mem_rsvmap(fdt) + offset;

	if (!can_assume(VALID_INPUT)) {
		if (absoffset < fdt_off_mem_rsvmap(fdt))
			return NULL;
		if (absoffset > fdt_totalsize(fdt) -
		    sizeof(struct fdt_reserve_entry))
			return NULL;
	}
	return fdt_mem_rsv_(fdt, n);
}

int fdt_get_mem_rsv(const void *fdt, int n, uint64_t *address, uint64_t *size)
{
	const struct fdt_reserve_entry *re;

	FDT_RO_PROBE(fdt);
	re = fdt_mem_rsv(fdt, n);
	if (!can_assume(VALID_INPUT) && !re)
		return -FDT_ERR_BADOFFSET;

	*address = fdt64_ld_(&re->address);
	*size = fdt64_ld_(&re->size);

