/* 학습 해설
 * DTB 다음 property·NOP 건너뛰기와 구조 종료
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * tag 순회에서 PROP이면 그 offset을 반환하고 NOP만 계속 건너뜁니다. BEGIN_NODE나 END_NODE 등에서는 NOTFOUND이며 정상 FDT_END가 property 영역에서 나오면 BADSTRUCTURE입니다. nextoffset 음수 오류도 전달하므로 모든 끝 tag를 동일한 정상 종료로 취급하지 않습니다.
 * property NOP 뒤 다음 property 또는 child로 진행하는 흐름을 추적합니다. node의 property 목록과 전체 node 순회는 다른 범위를 갖습니다.
 */
static int nextprop_(const void *fdt, int offset)
{
	uint32_t tag;
	int nextoffset;

	do {
		tag = fdt_next_tag(fdt, offset, &nextoffset);

		switch (tag) {
		case FDT_END:
			if (nextoffset >= 0)
				return -FDT_ERR_BADSTRUCTURE;
			else
				return nextoffset;

		case FDT_PROP:
			return offset;
		}
		offset = nextoffset;
	} while (tag == FDT_NOP);

	return -FDT_ERR_NOTFOUND;
}

