/* 학습 해설
 * DTB child 검색·depth1과 이름 길이
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * parent 기준 depth0에서 next_node를 반복하고 depth1 node만 이름 비교합니다. 후손 depth2는 매칭 대상이 아니며 parent 범위에서 depth가 음수가 되면 NOTFOUND입니다. 중간 탐색 오류는 offset으로 전달합니다. 이름 substring 인자와 unit address 비교를 결합하는 선형 검색입니다.
 * soc 바로 아래 ethernet과 그 후손을 구별합니다. 고정 fixture의 child 검색과 ancestor 전체 검색을 다른 API로 연결합니다.
 */
int fdt_subnode_offset_namelen(const void *fdt, int offset,
			       const char *name, int namelen)
{
	int depth;

	FDT_RO_PROBE(fdt);

	for (depth = 0;
	     (offset >= 0) && (depth >= 0);
	     offset = fdt_next_node(fdt, offset, &depth))
		if ((depth == 1)
		    && fdt_nodename_eq_(fdt, offset, name, namelen))
			return offset;

	if (depth < 0)
		return -FDT_ERR_NOTFOUND;
	return offset; /* error */
}

int fdt_subnode_offset(const void *fdt, int parentoffset,
		       const char *name)
{
	return fdt_subnode_offset_namelen(fdt, parentoffset, name, strlen(name));
}

