/* 학습 해설
 * DTB node 이름 조회·검사 후 내부 pointer
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 최소 probe와 BEGIN_NODE offset 검사를 통과한 뒤 node header의 이름 pointer를 반환합니다. 실패면 NULL이고 len 출력이 있으면 오류를 적습니다. 정상 최신 이름 길이는 NUL 전의 문자 수이며 새 할당 복사본이 아니라 blob 안의 문자열입니다.
 * ethernet@100의 길이12와 pointer 수명을 확인합니다. node tag 위치가 아닌 property 위치를 이름 조회에 주면 검사 조건이 다름을 읽습니다.
 */
const char *fdt_get_name(const void *fdt, int nodeoffset, int *len)
{
	const struct fdt_node_header *nh = fdt_offset_ptr_(fdt, nodeoffset);
	const char *nameptr;
	int err;

	if (((err = fdt_ro_probe_(fdt)) < 0)
	    || ((err = fdt_check_node_offset_(fdt, nodeoffset)) < 0))
			goto fail;

	nameptr = nh->name;

	if (!can_assume(LATEST) && fdt_version(fdt) < 0x10) {
		/*
		 * For old FDT versions, match the naming conventions of V16:
		 * give only the leaf name (after all /). The actual tree
		 * contents are loosely checked.
		 */
		const char *leaf;
		leaf = strrchr(nameptr, '/');
		if (leaf == NULL) {
			err = -FDT_ERR_BADSTRUCTURE;
			goto fail;
		}
		nameptr = leaf+1;
	}

