 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 공개 namelen struct 함수는 version16 미만을 거부하고 내부 이름 검색에 poffset NULL을 전달합니다. 일반 get_property는 strlen(name)으로 이 함수를 사용합니다. substring 이름과 NUL 전체 이름의 입력 방식은 달라도 struct 형식 제한은 같은 층에서 적용됩니다.
 * 값만 필요할 때 getprop, tag/len/nameoff 구조가 필요할 때 get_property를 비교합니다. 공개 wrapper와 내부 helper의 version 조건을 주석으로 구별합니다.
 */
const struct fdt_property *fdt_get_property_namelen(const void *fdt,
						    int offset,
						    const char *name,
						    int namelen, int *lenp)
{
	/* Prior to version 16, properties may need realignment
	 * and this API does not work. fdt_getprop_*() will, however. */
	if (!can_assume(LATEST) && fdt_version(fdt) < 0x10) {
		if (lenp)
			*lenp = -FDT_ERR_BADVERSION;
		return NULL;
	}

	return fdt_get_property_namelen_(fdt, offset, name, namelen, lenp,
					 NULL);
}


const struct fdt_property *fdt_get_property(const void *fdt,
					    int nodeoffset,
					    const char *name, int *lenp)
{
	return fdt_get_property_namelen(fdt, nodeoffset, name,
					strlen(name), lenp);
}

