/* 학습 해설
 * DTB offset으로 value·선택 이름 출력과 오류 전달
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 내부 struct 조회 뒤 namep가 있으면 nameoff 문자열을 조회해 이름 pointer를 전달합니다. 기본 경로에서 이름 조회가 실패하면 lenp에 그 오류를 적고 NULL입니다. namep가 NULL이면 이 이름 조회 단계를 생략합니다. 마지막 value 위치에는 구형 realignment도 적용합니다.
 * 실제 ethernet의 네 property를 offset으로 순회해 이름과 len을 함께 읽습니다. 선택 출력이 추가 검사를 유발하는 조건과 value의 byte pointer를 구별합니다.
 */
const void *fdt_getprop_by_offset(const void *fdt, int offset,
				  const char **namep, int *lenp)
{
	const struct fdt_property *prop;

	prop = fdt_get_property_by_offset_(fdt, offset, lenp);
	if (!prop)
		return NULL;
	if (namep) {
		const char *name;
		int namelen;

		if (!can_assume(VALID_INPUT)) {
			name = fdt_get_string(fdt, fdt32_ld_(&prop->nameoff),
					      &namelen);
			*namep = name;
			if (!name) {
				if (lenp)
					*lenp = namelen;
				return NULL;
			}
		} else {
			*namep = fdt_string(fdt, fdt32_ld_(&prop->nameoff));
		}
	}

