/* 학습 해설
 * DTB getprop wrapper·value pointer와 수명
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * getprop는 strlen(name)을 namelen value helper에 전달합니다. 성공 pointer는 blob 안의 property data이며 lenp는 byte 길이입니다. 없는 이름은 NULL과 NOTFOUND로 확인합니다. pointer 반환만으로 숫자 endian이나 문자열 NUL 규약을 알 수 없으므로 사용하는 property 형식을 함께 해석합니다.
 * answer의4바이트를 fdt32_ld로 읽고 compatible는 NUL 목록으로 해석합니다. 같은 void pointer 조회라도 자료 형식에 따라 사용법이 다른 이유를 적습니다.
 */
const void *fdt_getprop(const void *fdt, int nodeoffset,
			const char *name, int *lenp)
{
	return fdt_getprop_namelen(fdt, nodeoffset, name, strlen(name), lenp);
}

uint32_t fdt_get_phandle(const void *fdt, int nodeoffset)
{
	const fdt32_t *php;
	int len;

	/* FIXME: This is a bit sub-optimal, since we potentially scan
	 * over all the properties twice. */
	php = fdt_getprop(fdt, nodeoffset, "phandle", &len);
	if (!php || (len != sizeof(*php))) {
		php = fdt_getprop(fdt, nodeoffset, "linux,phandle", &len);
		if (!php || (len != sizeof(*php)))
			return 0;
	}

	return fdt32_ld_(php);
}

