/* 학습 해설
 * DTB 경로의 property·실패한 path와 출력 길이
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * 먼저 path를 node offset으로 해결하고 음수면 NULL을 반환합니다. 그 경로 실패 분기에는 lenp 대입이 없습니다. 정상 path이면 이름 길이 제한 getprop를 사용합니다. caller는 NULL 결과에서 lenp가 모든 경로 오류를 담는다고 가정하지 않아야 합니다.
 * /aliases와 /__symbols__의 property 조회가 이 helper를 공유하는 구조를 적습니다. 선택 출력의 실제 대입 위치와 caller의 short-circuit 검사를 읽습니다.
 */
static const void *fdt_path_getprop_namelen(const void *fdt, const char *path,
					    const char *propname, int propnamelen,
					    int *lenp)
{
	int offset = fdt_path_offset(fdt, path);

	if (offset < 0)
		return NULL;

	return fdt_getprop_namelen(fdt, offset, propname, propnamelen, lenp);
}

const char *fdt_get_alias_namelen(const void *fdt,
				  const char *name, int namelen)
{
	int len;
	const char *alias;

	alias = fdt_path_getprop_namelen(fdt, "/aliases", name, namelen, &len);

	if (!can_assume(VALID_DTB) &&
	    !(alias && len > 0 && alias[len - 1] == '\0' && *alias == '/'))
		return NULL;

	return alias;
}

