/* 학습 해설
 * DTB NUL 문자열 목록·contains와 byte 경계
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * NUL로 이어진 문자열 목록을 순회하며 대상 strlen+1 byte를 비교해 같으면1입니다. 다르면 주어진 listlen 안에서 다음 NUL을 찾아 진행하고 없으면0입니다. 원본은 listlen>=대상strlen 조건에서 비교하므로 일부 malformed 경계의 추가 byte 읽기 가능성을 별도로 검토해야 합니다.
 * 정상 compatible 두 문자열에서 두 번째를 찾는 실제 fixture를 읽습니다. listlen과 비교 길이len+1이 다른 조건임을 적고 모든 malformed byte buffer 안전성으로 확장하지 않습니다.
 */
int fdt_stringlist_contains(const char *strlist, int listlen, const char *str)
{
	int len = strlen(str);
	const char *p;

	while (listlen >= len) {
		if (memcmp(str, strlist, len+1) == 0)
			return 1;
		p = memchr(strlist, '\0', listlen);
		if (!p)
			return 0; /* malformed strlist.. */
		listlen -= (p-strlist) + 1;
		strlist = p + 1;
	}
	return 0;
}

