/* 학습 해설
 * DTB 문자열 목록 개수·bounded strnlen 검증
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * property 조회 뒤 끝 pointer를 정하고 남은 길이 안에서 strnlen+1을 계산합니다. 그 끝이 property end를 넘으면 마지막NUL 부재로 BADVALUE입니다. 각 정상 문자열마다 count를 늘리며 empty property는0개, 조회 실패는 해당 음수 오류입니다.
 * 두 compatible는2, 길이0은0, NUL 없는 xyz는 BADVALUE인 실제 fixture를 비교합니다. 빈 value와 빈 문자열 하나NUL의 개수를 구별합니다.
 */
int fdt_stringlist_count(const void *fdt, int nodeoffset, const char *property)
{
	const char *list, *end;
	int length, count = 0;

	list = fdt_getprop(fdt, nodeoffset, property, &length);
	if (!list)
		return length;

	end = list + length;

	while (list < end) {
		length = strnlen(list, end - list) + 1;

		/* Abort if the last string isn't properly NUL-terminated. */
		if (list + length > end)
			return -FDT_ERR_BADVALUE;

		list += length;
		count++;
	}

	return count;
}

