/* 학습 해설
 * DTB compatible node 검색·부재는 넘기고 오류 전달
 * flat DTB에서 이름·property·경로·별칭·조상·phandle·NUL 문자열 목록을 탐색하는 자료 표현, 순회 알고리즘, 오류와 사용 계약을 읽습니다.
 * startoffset 다음 node부터 전체 순회하며 checker0이면 첫 matching node를 반환합니다. checker NOTFOUND는 해당 node의 compatible 부재로 넘기고 그 외 음수 오류는 전달합니다. 이름 property 스캔과 node 순회가 겹치는 비용을 FIXME로 설명합니다.
 * root 등 compatible 없는 node를 넘어 eth를 찾는 실제 fixture를 읽습니다. 정상 불일치1과 부재 NOTFOUND가 모두 계속 순회하는 조건을 적습니다.
 */
int fdt_node_offset_by_compatible(const void *fdt, int startoffset,
				  const char *compatible)
{
	int offset, err;

	FDT_RO_PROBE(fdt);

	/* FIXME: The algorithm here is pretty horrible: we scan each
	 * property of a node in fdt_node_check_compatible(), then if
	 * that didn't find what we want, we scan over them again
	 * making our way to the next node.  Still it's the easiest to
	 * implement approach; performance can come later. */
	for (offset = fdt_next_node(fdt, startoffset, NULL);
	     offset >= 0;
	     offset = fdt_next_node(fdt, offset, NULL)) {
		err = fdt_node_check_compatible(fdt, offset, compatible);
		if ((err < 0) && (err != -FDT_ERR_NOTFOUND))
			return err;
		else if (err == 0)
			return offset;
	}

	return offset; /* error from fdt_next_node() */
}

