/* 학습 해설
 * DTB 쓰기 layout·reserve→structure→strings 순서
 * DTB 가변 수정의 block 배치, tail splice와 metadata, 이름 재사용/원복, 예약·property·node 수정, packing과 format 변환의 원리를 읽습니다.
 * read-write 구현은 reserve 시작이8 정렬 header 뒤이고 structure가 reserve 뒤, strings가 structure 뒤, strings끝이total 안인지 확인합니다. 이 도구가 쓰기에 기대하는 배치와 명세가 허용하는 모든 배치는 다릅니다. 재배치가 필요한 자료는 open_into에서 다루며 이 helper는 검사 결과만 계산합니다.
 * 각 block의 시작·크기·끝을 네 부등식으로 적습니다. sequential writer의 초기 reserve48과 pack의40이 모두 header40 뒤인 관계를 읽습니다.
 */
static int fdt_blocks_misordered_(const void *fdt,
				  int mem_rsv_size, int struct_size)
{
	return (fdt_off_mem_rsvmap(fdt) < FDT_ALIGN(sizeof(struct fdt_header), 8))
		|| (fdt_off_dt_struct(fdt) <
		    (fdt_off_mem_rsvmap(fdt) + mem_rsv_size))
		|| (fdt_off_dt_strings(fdt) <
		    (fdt_off_dt_struct(fdt) + struct_size))
		|| (fdt_totalsize(fdt) <
		    (fdt_off_dt_strings(fdt) + fdt_size_dt_strings(fdt)));
}

static int fdt_rw_probe_(void *fdt)
{
	if (can_assume(VALID_DTB))
		return 0;
	FDT_RO_PROBE(fdt);

	if (!can_assume(LATEST) && fdt_version(fdt) < 17)
		return -FDT_ERR_BADVERSION;
	if (fdt_blocks_misordered_(fdt, sizeof(struct fdt_reserve_entry),
				   fdt_size_dt_struct(fdt)))
		return -FDT_ERR_BADLAYOUT;
	if (!can_assume(LATEST) && fdt_version(fdt) > 17)
		fdt_set_version(fdt, 17);

